14	
15	import { cn } from "@/lib/utils";
16	
17	import { Avatar } from "@/components/Common/Avatar";
18	import { PatientSwitcherSheet } from "@/components/Patient/PatientSwitcherSheet";
19	
20	import { usePatientContext } from "@/hooks/usePatientUser";
21	
22	/** How long the "now showing records for X" confirmation stays up. */
23	const SWITCH_NOTICE_MS = 4000;
24	
25	const TABS = [
26	  { key: "home", href: "/patient/home", icon: Home, label: "home" },
27	  {
28	    key: "visits",
29	    href: "/patient/visits",
30	    icon: CalendarDays,
31	    label: "visits",
32	  },
33	  {
34	    key: "records",
35	    href: "/patient/records",
36	    icon: FolderClosed,
37	    label: "records",
38	  },
39	  { key: "profile", href: "/patient/profile", icon: User, label: "profile" },
40	] as const;
41	
42	/** `Anitha Ravindran` → `Anitha R.` so the header chip stays on one line. */
43	function abbreviateName(name: string): string {
44	  const parts = name.trim().split(/\s+/);
45	  if (parts.length < 2) {
46	    return parts[0] ?? "";
47	  }
48	  return `${parts[0]} ${parts[parts.length - 1][0]}.`;
49	}
50	
51	interface PatientAppShellProps {
52	  children: React.ReactNode;
53	  /**
54	   * Omit on the home screen to get the large "Viewing <patient>" chip.
55	   * Provide it elsewhere to get a page title alongside a compact chip.
56	   */
57	  title?: string;
58	  /** Renders a back affordance instead of the tab bar's implicit navigation. */
59	  backTo?: string;
60	  /** Detail screens hide the tab bar so the page owns the full height. */
61	  hideTabs?: boolean;
62	  /** Trailing header content, e.g. a download action on detail screens. */
63	  headerAction?: React.ReactNode;
64	  /** Underline tabs rendered inside the header — use `PatientHeaderTabs`. */
65	  headerTabs?: React.ReactNode;
66	}
67	
68	/**
69	 * The section switcher used by Records and Visits. Lives here so both screens
70	 * share one implementation and stay visually identical.
71	 */
72	export function PatientHeaderTabs<T extends string>({
73	  tabs,
74	  value,
75	  onChange,
76	}: {
77	  tabs: { key: T; label: string }[];
78	  value: T;
79	  onChange: (key: T) => void;
80	}) {
81	  return (
82	    <div className="flex gap-6 px-4">
83	      {tabs.map((tab) => (
84	        <button
85	          key={tab.key}
86	          type="button"
87	          onClick={() => onChange(tab.key)}
88	          aria-current={value === tab.key ? "page" : undefined}
89	          className={cn(
90	            "-mb-px flex min-h-11 items-center border-b-[2.5px] pb-2.5 text-sm transition-colors",
91	            value === tab.key
92	              ? "border-primary-700 font-bold text-primary-700"
93	              : "border-transparent font-semibold text-gray-600 hover:text-gray-900",
94	          )}
95	        >
96	          {tab.label}
97	        </button>
98	      ))}
99	    </div>
100	  );
101	}
102	
103	export function PatientAppShell({
104	  children,
105	  title,
106	  backTo,
107	  hideTabs,
108	  headerAction,
109	  headerTabs,
110	}: PatientAppShellProps) {
111	  const { t } = useTranslation();
112	  const path = usePath();
113	  const { selectedPatient, patients, isLoadingPatients } = usePatientContext();
114	
115	  const [switcherOpen, setSwitcherOpen] = useState(false);
116	  const [switchedTo, setSwitchedTo] = useState<string | null>(null);
117	
118	  // Every patient screen is scoped to a profile, so with none linked the only
119	  // useful destination is the picker, which offers to create one.
120	  const hasNoProfiles = !isLoadingPatients && patients?.length === 0;
121	  useEffect(() => {
122	    if (hasNoProfiles) {
123	      navigate("/patient/select-profile", { replace: true });
124	    }
125	  }, [hasNoProfiles]);
126	
127	  useEffect(() => {
128	    if (!switchedTo) {
129	      return;
130	    }
131	    const timer = setTimeout(() => setSwitchedTo(null), SWITCH_NOTICE_MS);
132	    return () => clearTimeout(timer);
133	  }, [switchedTo]);
134	
135	  const canSwitch = (patients?.length ?? 0) > 1;
136	
137	  const switcherChip = selectedPatient && (
138	    <button
139	      type="button"
140	      onClick={() => setSwitcherOpen(true)}
141	      disabled={!canSwitch}
142	      className={cn(
143	        "flex min-h-11 items-center gap-2 rounded-full border border-gray-200 bg-gray-50 py-1 pl-1 pr-3",
144	        canSwitch && "hover:border-gray-300",
145	      )}
146	    >
147	      <Avatar
148	        name={selectedPatient.name}
149	        className={cn("rounded-full", title ? "size-6" : "size-7")}
150	      />
151	      {title ? (
152	        <span className="text-sm font-semibold text-gray-900">
153	          {abbreviateName(selectedPatient.name)}
154	        </span>
155	      ) : (
156	        <span className="flex flex-col items-start leading-tight">
157	          <span className="text-[10px] font-bold uppercase tracking-wider text-gray-500">
158	            {t("patient_shell__viewing")}
159	          </span>
160	          <span className="text-sm font-bold text-gray-900">
161	            {abbreviateName(selectedPatient.name)}
162	          </span>
163	        </span>
164	      )}
165	      {canSwitch && <ChevronDown className="size-3.5 text-gray-500" />}
166	    </button>
167	  );
168	
169	  const tabBar = (
170	    <>
171	      {TABS.map((tab) => {
172	        const isActive = path?.startsWith(tab.href);
173	        const Icon = tab.icon;
174	        return (
175	          <Link
176	            key={tab.key}
177	            href={tab.href}
178	            className={cn(
179	              "flex flex-col items-center justify-center gap-1 py-1 transition-colors",
180	              isActive
181	                ? "text-primary-700"
182	                : "text-gray-400 hover:text-gray-600",
183	            )}
184	            aria-current={isActive ? "page" : undefined}
