(() => {
  const out = [];
  const b = document.querySelector('[data-slot="patient-badge"]');
  if (b) { const cs = getComputedStyle(b), r = b.getBoundingClientRect(); out.push({ el: 'PatientBadge', text: b.textContent, fs: cs.fontSize, h: Math.round(r.height), bg: cs.backgroundColor }); }
  const chip = document.querySelector('header button');
  if (chip) { const r = chip.getBoundingClientRect(); out.push({ el: 'headerChip', x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }); }
  const tile = document.querySelectorAll('main a, main button');
  const quick = Array.from(tile).slice(0, 4).map(e => { const r = e.getBoundingClientRect(); return { t: e.textContent.trim(), h: Math.round(r.height) }; });
  out.push({ el: 'quickActions', quick });
  const avatar = document.querySelector('header button span');
  if (avatar) { const cs = getComputedStyle(avatar), r = avatar.getBoundingClientRect(); out.push({ el: 'chipAvatar', bg: cs.backgroundColor, color: cs.color, w: Math.round(r.width), h: Math.round(r.height), text: avatar.textContent }); }
  return out;
})()

