3	
4	import { Card } from "@/components/ui/card";
5	import { Label } from "@/components/ui/label";
6	
7	import { ShortcutBadge } from "@/Utils/keyboardShortcutComponents";
8	import { PatientAge } from "@/components/Patient/PatientAge";
9	import { resourceTypeToResourcePathSlug } from "@/components/Schedule/useScheduleResource";
10	import TagBadge from "@/components/Tags/TagBadge";
11	import { Button } from "@/components/ui/button";
