14	import useBreakpoints from "@/hooks/useBreakpoints";
15	import usePatientExtensionData from "@/hooks/usePatientExtensionData";
16	import { formatSlotTimeRange } from "@/pages/Appointments/utils";
17	import { PatientRead } from "@/types/emr/patient/patient";
18	import { FacilityRead } from "@/types/facility/facility";
