20	import {
21	  AppointmentRead,
22	  formatScheduleResourceName,
23	} from "@/types/scheduling/schedule";
24	import { TokenRead, renderTokenNumber } from "@/types/tokens/token/token";
25	import { formatDate } from "date-fns";
26	import { PrinterIcon } from "lucide-react";
27	import { Link } from "raviger";
28	import { formatPhoneNumberIntl } from "react-phone-number-input";
29	
30	interface BaseProps {
31	  id?: string;
32	  facility?: FacilityRead;
33	  inPrintMode?: boolean;
34	}
35	
36	type Props =
37	  | (BaseProps & { token: TokenRead; appointment?: AppointmentRead })
38	  | (BaseProps & { token?: TokenRead; appointment: AppointmentRead });
39	
40	const TokenCard = ({
41	  id,
42	  token,
43	  facility,
44	  appointment,
45	  inPrintMode = false,
46	}: Props) => {
47	  const { t } = useTranslation();
48	  const isLargeScreen = useBreakpoints({ lg: true, default: false });
49	  useShortcutSubContext();
50	
51	  // Get patient from token or appointment (one is always defined per Props type)
52	  const patient = token?.patient ?? appointment?.patient;
53	  // Get patient with identifiers (appointment.patient has more data)
54	  const patientWithIdentifiers = appointment?.patient as
55	    PatientRead | undefined;
56	  const patientTags =
57	    patientWithIdentifiers?.instance_tags ?? patient?.instance_tags;
58	
59	  const appointmentTags = appointment?.tags ?? [];
60	
61	  const patientExtensionData = usePatientExtensionData(
62	    appointment?.patient?.extensions,
63	    "appointment_print",
64	  );
65	
66	  return (
67	    <Card
68	      id={id}
69	      className="p-2 border border-gray-200 relative transition-all duration-300 ease-in-out print:scale-100 print:rotate-0 print:shadow-none print:hover:scale-100 print:hover:rotate-0 print:hover:shadow-none bg-gray-100"
70	    >
71	      <div className="flex flex-col px-1">
72	        {token && <p className="font-semibold">{renderTokenNumber(token)}</p>}
73	        {appointment && (
74	          <p className="font-semibold">
75	            {t("appointment")} {t(appointment.status)}
76	          </p>
77	        )}
78	        {appointment && (
79	          <p className="text-gray-700">
80	            {formatScheduleResourceName(appointment)}
81	          </p>
82	        )}
83	      </div>
84	      <div className="flex flex-col gap-2 bg-white rounded-md p-4 shadow-md mt-2 ">
85	        <div className="flex flex-row justify-between">
86	          <div className=" flex flex-col items-start justify-between">
87	            {patient && (
88	              <div>
89	                <Label className="text-gray-600 text-sm">
90	                  {t("patient_name")}:
91	                </Label>
92	                <p className="font-semibold wrap-break-word text-sm">
93	                  {patient.name || "--"}
94	                </p>
95	                <p className="pl-1 text-sm text-gray-600 font-medium">
96	                  <PatientAge patient={patient} />,{" "}
97	                  {t(`GENDER__${patient.gender}`)}
98	                </p>
99	                {patientExtensionData.map((data) => {
100	                  return (
101	                    <div key={data.name} className="hidden print:block">
102	                      <Label className="text-gray-600 text-sm">
103	                        {data.name}:
104	                      </Label>
105	                      <p className="font-semibold text-sm">{data.value}</p>
106	                    </div>
107	                  );
108	                })}
109	                {patientWithIdentifiers?.instance_identifiers
110	                  ?.filter(
111	                    (identifier) =>
112	                      identifier.config.config.use ===
113	                      PatientIdentifierUse.official,
114	                  )
115	                  .map((identifier) => (
116	                    <div key={identifier.config.id}>
117	                      <Label className="text-gray-600 text-sm">
118	                        {identifier.config.config.display}:
119	                      </Label>
120	                      <p className="font-semibold text-sm">
121	                        {identifier.value}
122	                      </p>
123	                    </div>
124	                  ))}
125	                {inPrintMode && patient.address?.trim() && (
126	                  <div>
127	                    <Label className="text-gray-600 text-sm">
128	                      {t("address")}:
129	                    </Label>
130	                    <p className="font-semibold text-sm whitespace-pre-wrap">
131	                      {patient.address}
132	                    </p>
133	                    <p className="font-semibold text-sm">
134	                      {formatPhoneNumberIntl(patient.phone_number) ||
135	                        patient.phone_number}
136	                    </p>
137	                  </div>
138	                )}
139	              </div>
140	            )}
141	
142	            <div className="flex justify-between items-start gap-4">
143	              <div className="flex-1 min-w-0">
144	                <div className="space-y-2 flex-1 min-w-0">
145	                  {appointment && (
146	                    <>
147	                      <div>
148	                        <Label className="text-gray-600 text-sm">
149	                          {t(
150	                            `schedulable_resource__${appointment.resource_type}`,
151	                          )}
152	                          :
153	                        </Label>
154	                        <p className="font-semibold wrap-break-word text-sm">
155	                          {formatScheduleResourceName(appointment)}
156	                        </p>
157	                      </div>
158	                      <Separator />
159	                      <div>
160	                        <p className="text-sm font-semibold text-gray-900">
161	                          {appointment.token_slot.availability.name}
162	                        </p>
163	                        <p className="text-sm font-semibold text-gray-600 flex gap-2">
164	                          <span className="text-sm font-semibold text-gray-600">
165	                            {formatDate(
166	                              appointment.token_slot.start_datetime,
167	                              "EEE, dd MMM",
168	                            )}
169	                          </span>
170	                          <span className="text-sm font-semibold text-gray-600">
171	                            {formatSlotTimeRange(appointment.token_slot)}
172	                          </span>
173	                        </p>
174	                        <div className="flex flex-wrap gap-1 my-2">
175	                          {patientTags?.map((tag) => (
176	                            <TagBadge
177	                              key={tag.id}
178	                              tag={tag}
179	                              hierarchyDisplay
180	                              className="text-xs"
181	                              variant="outline"
182	                            />
183	                          ))}
184	                          {appointmentTags?.map((tag) => (
185	                            <TagBadge
186	                              key={tag.id}
187	                              tag={tag}
188	                              hierarchyDisplay
189	                              className="text-xs"
190	                              variant="outline"
191	                            />
192	                          ))}
193	                        </div>
194	                      </div>
195	                    </>
196	                  )}
197	                </div>
198	
199	                {facility && (
200	                  <div className="flex-1 min-w-0">
201	                    <h3 className="text-sm font-semibold tracking-tight wrap-break-word">
202	                      {facility.name}
203	                    </h3>
204	                    <div className="text-sm text-gray-600">
205	                      <span>{facility.pincode}</span>
206	                      <div className="whitespace-normal">{`Ph.: ${facility.phone_number}`}</div>
207	                    </div>
208	                  </div>
209	                )}
210	              </div>
211	            </div>
212	          </div>
213	          <div className="flex flex-col gap-2 items-end">
214	            {token && (
215	              <div className="items-end">
216	                <Label className="text-gray-600 text-sm whitespace-nowrap justify-end">
217	                  {t("token_no")}
218	                </Label>
219	                <p className="text-2xl font-bold justify-end flex">
220	                  {renderTokenNumber(token)}
221	                </p>
222	              </div>
223	            )}
224	            <div>
225	              <QRCodeSVG
226	                size={isLargeScreen ? 96 : 60}
227	                value={patient?.id || ""}
228	                className="ml-2"
229	              />
230	            </div>
231	          </div>
232	        </div>
233	        {appointment && !inPrintMode && (
234	          <div>
235	            <Separator />
236	            <div className="pt-3 mx-4 flex gap-2 justify-between print:hidden">
237	              <Button
238	                variant="link"
239	                className="underline font-semibold text-base capitalize text-gray-950"
240	              >
241	                <Link
242	                  basePath="/"
243	                  href={`/facility/${appointment.facility.id}/${resourceTypeToResourcePathSlug[appointment.resource_type]}/${appointment.resource.id}/queues/${appointment.token?.queue.id}`}
244	                >
245	                  {t("queue_board")}
246	                </Link>
247	              </Button>
248	              <Button
249	                variant="outline"
250	                onClick={() => print()}
251	                className="text-base text-gray-950 font-semibold"
252	              >
253	                <PrinterIcon className="size-4 mr-2" />
254	                {t("print_token")}
255	                <ShortcutBadge actionId="print-button" />
256	              </Button>
257	            </div>
258	          </div>
259	        )}
260	      </div>
261	    </Card>
262	  );
263	};
264	
265	export { TokenCard };
